/// Look up Grapheme_Cluster_Break property for a character.
#[must_use]
pub fn gcb(ch: char) -> Gcb {
    let cp = ch as u32;
    // Check Extended_Pictographic first (not in GCB_RANGES)
    if is_extended_pictographic(cp) {
        return Gcb::ExtendedPictographic;
    }
    // Binary search on range table
    match GCB_RANGES.binary_search_by(|&(start, end, _)| {
        if cp < start {
            std::cmp::Ordering::Greater
        } else if cp > end {
            std::cmp::Ordering::Less
        } else {
            std::cmp::Ordering::Equal
        }
    }) {
        Ok(i) => GCB_RANGES[i].2,
        Err(_) => Gcb::Other,
    }
}

